var DATA = {"op": "Charge a card", "pattern": "Idempotency key header", "key": "UUID per user action", "retry": "Safe to retry with same key", "deliveries": "k1:charge $10|k1:charge $10|k2:charge $10"};
console.log("Operation: " + DATA.op + " | Pattern: " + DATA.pattern);
console.log("Key design: " + DATA.key);
var seen = {}, effects = 0;
var deliveries = DATA.deliveries.split("|").map(function (s) { return s.trim(); });
deliveries.forEach(function (d, i) {
  var key = d.split(":")[0];
  if (seen[key]) {
    console.log("  delivery " + (i + 1) + " [" + d + "]: DUPLICATE key -> no new effect (" + DATA.retry + ")");
  } else {
    seen[key] = true; effects++;
    console.log("  delivery " + (i + 1) + " [" + d + "]: new key -> effect applied");
  }
});
console.log("RESULT: " + deliveries.length + " deliveries collapsed to " + effects + " effect(s) — idempotent.");

